enum ReaderError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case MetadataExchange(message: String
    )
    case Backup(message: String
    )
    case Io(message: String
    )
    case Storage(message: String
    )
    case Decode(message: String
    )
    case GraphemeTooLong
    case BinaryContent
    case TextCapacityExceeded
    case NotFound
    case EmptyBook
    case InvalidSettings
    case Paused
    case ImportBusy
    case SourceChanged
    case IncompatibleStore
    case StoreTooNew(version: UInt32, current: UInt32
    )
    case CloudAccountChanged
    case InvalidRange
    case SearchPattern(message: String
    )
    case SearchLineTooLong

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ReaderError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeReaderError: FfiConverterRustBuffer {
    typealias SwiftType = ReaderError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ReaderError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .MetadataExchange(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Backup(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Decode(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .GraphemeTooLong
        case 7: return .BinaryContent
        case 8: return .TextCapacityExceeded
        case 9: return .NotFound
        case 10: return .EmptyBook
        case 11: return .InvalidSettings
        case 12: return .Paused
        case 13: return .ImportBusy
        case 14: return .SourceChanged
        case 15: return .IncompatibleStore
        case 16: return .StoreTooNew(
            version: try FfiConverterUInt32.read(from: &buf), 
            current: try FfiConverterUInt32.read(from: &buf)
            )
        case 17: return .CloudAccountChanged
        case 18: return .InvalidRange
        case 19: return .SearchPattern(
            message: try FfiConverterString.read(from: &buf)
            )
        case 20: return .SearchLineTooLong

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ReaderError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .MetadataExchange(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Backup(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Io(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Decode(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case .GraphemeTooLong:
            writeInt(&buf, Int32(6))
        
        
        case .BinaryContent:
            writeInt(&buf, Int32(7))
        
        
        case .TextCapacityExceeded:
            writeInt(&buf, Int32(8))
        
        
        case .NotFound:
            writeInt(&buf, Int32(9))
        
        
        case .EmptyBook:
            writeInt(&buf, Int32(10))
        
        
        case .InvalidSettings:
            writeInt(&buf, Int32(11))
        
        
        case .Paused:
            writeInt(&buf, Int32(12))
        
        
        case .ImportBusy:
            writeInt(&buf, Int32(13))
        
        
        case .SourceChanged:
            writeInt(&buf, Int32(14))
        
        
        case .IncompatibleStore:
            writeInt(&buf, Int32(15))
        
        
        case let .StoreTooNew(version,current):
            writeInt(&buf, Int32(16))
            FfiConverterUInt32.write(version, into: &buf)
            FfiConverterUInt32.write(current, into: &buf)
            
        
        case .CloudAccountChanged:
            writeInt(&buf, Int32(17))
        
        
        case .InvalidRange:
            writeInt(&buf, Int32(18))
        
        
        case let .SearchPattern(message):
            writeInt(&buf, Int32(19))
            FfiConverterString.write(message, into: &buf)
            
        
        case .SearchLineTooLong:
            writeInt(&buf, Int32(20))
        
        }
    }
}


